def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    seconds = nanoseconds // 1_000_000_000
    microseconds = (nanoseconds % 1_000_000_000) // 1_000
    if tz is None:
        return datetime.fromtimestamp(seconds, tz=timezone.utc) + timedelta(microseconds=microseconds)
    else:
        return datetime.fromtimestamp(seconds, tz=tz) + timedelta(microseconds=microseconds)

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, timezone

    if nanoseconds is None:
        return None

    try:
        total_seconds = nanoseconds / 1_000_000_000.0
        dt = datetime.fromtimestamp(total_seconds, timezone.utc)
        if tz is not None:
            dt = dt.astimezone(tz)
        return dt.time()
    except (TypeError, ValueError, OverflowError) as e:
        raise ValueError(f"Invalid nanoseconds value: {nanoseconds}") from e

