def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            try:
                if metadata is not None:
                    tx.metadata.update(metadata)
                if timeout is not None and timeout >= 0:
                    tx.timeout = timeout
            except Exception as e:
                logger.error(f"Error setting unit of work metadata or timeout: {e}")
                return None
            return func(tx, *args, **kwargs)
        return wrapper
    return decorator

def unit_of_work(metadata=None, timeout=None):
    """Decorator for transaction functions that allows extra control over how the transaction is carried out."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Implementation of the transaction function
            def transaction_function(tx):
                return func(tx, *args, **kwargs)

            # Apply metadata and timeout to the transaction
            with GraphDatabase.transaction(session, metadata=metadata, timeout=timeout) as tx:
                return transaction_function(tx)

        return wrapper

    return decorator

