    if maxsize <= 0:
        raise ValueError('maxsize must be positive')

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq
            self.prev = None
            self.next = None

    class doublyLinkedlist:
        def __init__(self):
            self.head, self.tail = Node(None, None, 0), Node(None, None, 0)
            self.head.next = self.tail
            self.tail.prev = self.head

        def append(self, node):
            p = self.tail.prev
            p.next = node
            node.prev = p
            node.next = self.tail
            self.tail.prev = node

        def move_to_head(self, node):
            self.remove(node)
            self.append(node)

        def remove(self, node):
            p = node.prev
            n = node.next
            p.next = n
            n.prev = p

    class HashTable:
        def __init__(self, capacity=128):
            self.capacity = capacity
            selfbucket = [None] * capacity
            self.size = 0

        def hash(self, key):
            return hash(key) % self.capacity

        def insert(self, key, value):
            index = self.hash(key)
            if self.bucket[index] is None:
                self.bucket[index] = doublyLinkedlist()
            self.bucket[index].append(Node(key, value))
            self.size += 1

        def remove(self, node):
            index = self.hash(node.key)
            self.bucket[index].remove(node)
            self.size -= 1

        def get(self, key):
            index = self.hash(key)
            if self.bucket[index] is not None:
                n = self.bucket[index].head.next
                while n is not self.bucket[index].tail:
                    if n.key == key:
                        self.bucket[index].move_to_head(n)
                        return n.value
                    n = n.next
            return None

        def keys(self):
            key_list = []
            for item in self.bucket:
                if item is not None:
                    n = item.head.next
                    while n is not item.tail:
                        key_list.append(n.key)
                        n = n.next
