    def get_lfu_key():
        min_freq = frequency.keys()[0]
        for key in frequency.keys():
            if frequency.get(key) < frequency.get(min_freq):
                min_freq = key
        for item in cache.bucket:
            if item is not None:
                n = item.head.next
                while n is not item.tail:
                    if n.key == min_freq:
                        return n.key
                    n = n.next
        return None

    def pop_lfu():
        lfu_key = get_lfu_key()
        if lfu_key is not None:
            for item in cache.bucket:
                if item is not None:
                    n = item.head.next
                    while n is not item.tail:
                        if n.key == lfu_key:
