def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord = np.atleast_1d(coord)
    weight = np.atleast_1d(weight)

    if len(coord) != len(weight):
        raise ValueError("The number of coordinates and weights must be the same.")

    for c, w in zip(coord, weight):
        if self._is_inside(c):
            self._data[int(c)] += w

    return self

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.ndim:
        raise ValueError("Coordinate dimension must match histogram dimension")

    for c in coord:
        if c < self.edges[0] or c >= self.edges[-1]:
            weight = 0
            break

    if weight != 0:
        bin_indices = np.searchsorted(self.edges, coord, side='right') - 1
        for index in zip(*bin_indices):
            self._counts[index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != len(self.edges) - 1:
        raise ValueError("Coordinate must have same dimension as histogram edges")

    bin_idx = []
    for i in range(len(coord)):
        idx = np.digitize(coord[i], self.edges[i])
        if idx > 0 and idx < len(self.edges[i]) - 1:
            bin_idx.append(idx)

    if bin_idx:
        for idx in bin_idx:
            self.values[idx] += weight
        return True
    return False

