def format(
    self,
    sql: Union[str, bytes],
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[Union[str, bytes], Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    from pypika import Query, Parameter, Table

    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    if self.SQLParams.in_style == ':':
        if not isinstance(params, Mapping):
            raise ValueError("Params must be a dictionary for named parameters")

        query = Query.from_(sql)
        for key, value in params.items():
            query = query.set(Parameter(key), value)

        formatted_sql = query.get_sql()
        out_params = {key: params[key] for key in params}
    else:
        if not isinstance(params, Sequence):
            raise ValueError("Params must be a sequence for ordinal parameters")

        query = Query.from_(sql)
        for index, value in enumerate(params):
            query = query.set(Parameter(index + 1), value)

        formatted_sql = query.get_sql()
        out_params = list(params)

    if isinstance(formatted_sql, bytes):
        formatted_sql = formatted_sql.decode('utf-8')

    return formatted_sql, out_params

