def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = []
    unused_digests = []

    for file in manifest_files:
        with open(file, 'r') as f:
            content = f.read()
            for digest in digests_used:
                if digest not in content:
                    missing_digests.append(digest)

    for digest in digests_used:
        if digest not in manifest_files:
            unused_digests.append(digest)

    if missing_digests or unused_digests:
        raise ValueError(f"Missing digests: {missing_digests}, Unused digests: {unused_digests}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = []

    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            lines = file.readlines()
            for line in lines:
                if line.startswith('digest:'):
                    digest = line.split(':')[1].strip()
                    if digest not in digests_used:
                        missing_digests.append(digest)

    unused_digests = list(set(digests_used) - set([line.split(':')[1].strip() for line in open(manifest_files[0], 'r').readlines() if line.startswith('digest:')]))

    if missing_digests:
        raise ValueError(f"Missing digests: {', '.join(missing_digests)}")
    if unused_digests:
        raise ValueError(f"Unused digests: {', '.join(unused_digests)}")

