    """

    if not isinstance(prior, InventoryValidator):
        raise ValueError('Input prior must be an InventoryValidator object')

    if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
        raise ValueError('Stoichiometry matrix shapes must match')

    if set(self.species) != set(prior.species):
        raise ValueError('Species sets must match')

    if not all(np.array_equal(self.propensities[i], prior.propensities[i]) for i in range(len(self.propensities))):
        raise ValueError('Propensities must match exactly')

    if self.parameters.keys() != prior.parameters.keys():
        raise ValueError('Parameter keys must match')

    for param in self.parameters.keys():
        if not np.array_equal(self.parameters[param], prior.parameters[param]):
            raise ValueError('Parameter values must match exactly')

    if self.gibbs_free_energy != prior.gibbs_free_energy:
        raise ValueError('Gibbs free energy must match')

