def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not all(isinstance(entry, list) for entry in fixity.values()):
        raise ValueError("Fixity block entries must be lists")

    referenced_files = set()
    for entry in fixity.values():
        for file_info in entry:
            if not isinstance(file_info, dict) or 'hash' not in file_info or 'path' not in file_info:
                raise ValueError("Invalid fixity block entry")
            referenced_files.add(file_info['path'])

    if not manifest_files.issuperset(referenced_files):
        raise ValueError("Fixity block references files not listed in manifest")

    valid_hashes = {
        'md5', 'sha256', 'sha512'
    }

    for entry in fixity.values():
        for file_info in entry:
            if file_info['hash'].lower() not in valid_hashes:
                raise ValueError("Invalid fixity hash type")

    print("Fixity validation passed.", file=sys.stderr)

