def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        indent += 2  # Increase indent for debug mode
    pretty_str = f"{' ' * indent}{{"
    for key, value in self.__dict__.items():
        pretty_str += f"\n{' ' * (indent + 4)}{key}: "
        if isinstance(value, dict):
            pretty_str += f"{{{', '.join(f'{k}: {v}' for k, v in value.items())}}}"
        else:
            pretty_str += str(value)
        pretty_str += ","
    pretty_str += f"\n{' ' * indent}}}"
    return pretty_str

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    lines = []
    indent_str = ' ' * indent
    if debug:
        lines.append(f"{indent_str}class: {self.__class__.__name__}")
    for attr in dir(self):
        if not attr.startswith("__"):
            value = getattr(self, attr)
            if callable(value):
                continue
            if isinstance(value, (list, dict, set)):
                value = self.pretty_print(value, indent + 2)
            lines.append(f"{indent_str}{attr}: {value}")
    return '\n'.join(lines)

