def addignored(ignored):
    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma. """
    gitignored_content = subprocess.check_output(['git', 'cat-file', '-p', 'HEAD:.gitignore']).decode('utf-8')
    ignored_files = [line.strip() for line in gitignored_content.split('\n') if line.strip()]
    ignored_files.sort()
    return ','.join(ignored_files)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    def git(args, error_message, cwd=None):
        output, status = subprocess.run(['git'] + args, capture_output=True, text=True, cwd=cwd)
        if status != 0:
            raise Exception(f"{error_message}: {output}")
        return output.strip()

    ignored_files = git(['status', '--ignored', '--porcelain'], "Failed to retrieve ignored files")
    ignored_files = [line.split()[1] for line in ignored_files.split('\n') if line]
    ignored_files.sort()

    return ','.join(ignored_files)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    try:
        output, _ = subprocess.Popen(['git', 'ls-files', '--exclude-standard', '--ignored'], stdout=subprocess.PIPE).communicate()
        files = output.decode('utf-8').split('\n')
        ignored_files = [file for file in files if file and any(fnmatch.fnmatch(file, pattern) for pattern in ignored)]
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        return f"Error: {e}"

