def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.strip()
    units_map = {
        'seconds': 'seconds',
        'minutes': 'minutes',
        'hours': 'hours',
        'days': 'days',
        'weeks': 'weeks',
        'months': 'days',  # Approximation, as timedelta does not support direct months
        'years': 'days'    # Approximation, as timedelta does not support direct years
    }

    unit = None
    for key, value in units_map.items():
        if frequency.endswith(key) or frequency.endswith(value):
            unit = key
            frequency = frequency[:-(len(key) + 1)].strip()
            break

    if unit is None:
        raise ValueError("Invalid frequency string")

    try:
        value = int(frequency)
    except ValueError:
        raise ValueError("Invalid frequency string")

    if value < 0:
        raise ValueError("Invalid frequency string")

    if unit == 'months' or unit == 'years':
        value *= 30  # Approximation for months and years

    return datetime.timedelta(**{units_map[unit]: value})

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    components = frequency.split()
    if len(components) != 2:
        raise ValueError("Invalid frequency format")

    number = components[0]
    unit = components[1].lower()

    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency format")

    if unit in ["seconds", "second"]:
        return datetime.timedelta(seconds=number)
    elif unit in ["minutes", "minute"]:
        return datetime.timedelta(minutes=number)
    elif unit in ["hours", "hour"]:
        return datetime.timedelta(hours=number)
    elif unit in ["days", "day"]:
        return datetime.timedelta(days=number)
    elif unit in ["weeks", "week"]:
        return datetime.timedelta(weeks=number)
    elif unit in ["months", "month"]:
        return datetime.timedelta(days=number * 30)
    elif unit in ["years", "year"]:
        return datetime.timedelta(days=number * 365)
    else:
        raise ValueError("Invalid frequency unit")

