def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        raise TypeError("commands must be a list of strings")

    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")

    final_args = commands + args
    try:
        if hide_stderr:
            stdout = subprocess.check_output(final_args, cwd=cwd, env=env, stderr=subprocess.DEVNULL)
        else:
            stdout = subprocess.check_output(final_args, cwd=cwd, env=env)

        if verbose:
            print(stdout.decode('utf-8'))

        return stdout
    except subprocess.CalledProcessError as e:
        msg = f"Command failed: {final_args}\nOutput: {e.output.decode('utf-8') if e.output else 'No output'}"
        raise RuntimeError(msg)

